(function(){
'use strict';
if(typeof DATA==='undefined' || typeof PUBLIC_DATA==='undefined') return;
const S=v=>(v==null?'':String(v));
const N=v=>S(v).toLowerCase().replace(/ё/g,'е').replace(/\s+/g,' ').trim();
const T='ардашникова анна наумовна';
const CAN='24б/ф314-персидский/5';
const OLD='24б/р214_1/5/(ф)';
const PUB='3 курс — филология — персидский';
function isTarget(r){
  if(!r || N(r.teacher)!==T || S(r.course).trim()!=='3 бакалавриат') return false;
  if(!N(r.discipline).includes('литература изучаемого региона')) return false;
  const g=N(r.group);
  return g===CAN || g===OLD || g===N(PUB);
}

// 01.09.2026. В студенческой сетке 3 курса филологов-персистов
// литература Ардашниковой оказалась наложена на языковой блок. Источник 29.08
// фиксирует структуру нагрузки: одна еженедельная пара + дополнительная пара
// через неделю, при этом чётность дополнительной пары не была подтверждена.
// Поэтому снимаем конфликтные текущие строки и НЕ выдумываем чётность.
for(let i=DATA.length-1;i>=0;i--){ if(isTarget(DATA[i])) DATA.splice(i,1); }

DATA.push({
  group:'24Б/Ф314-персидский/5',
  course:'3 бакалавриат',
  direction:'Филология',
  day:'Чт',
  time:'13:00',
  discipline:'Литература изучаемого региона',
  extra:'1-я пара еженедельно; общая нагрузка курса — 3 акад. ч/нед.',
  teacher:'Ардашникова Анна Наумовна',
  room_hint:'236',
  quality:'01.09.2026: конфликтная еженедельная литература филологов-персистов 3 курса снята из Вт/Ср 13:00, где она пересекалась с языковым блоком. Рабочий слот перенесён на Чт 13:00: он входит в заявленные Ардашниковой дни Вт/Ср/Чт/Пт и часы 10:40/13:00/14:40/16:20; преподаватель свободен; ауд.236 — обычная учебная аудитория, а не кафедра, и свободна в текущей сетке. Прямое пожелание преподавателя «лекции только в аудитории» соблюдено.'
});

DATA.push({
  group:'24Б/Ф314-персидский/5',
  course:'3 бакалавриат',
  direction:'Филология',
  day:'уточняется',
  time:'уточняется',
  discipline:'Литература изучаемого региона',
  extra:'2-я дополнительная пара через неделю; чётность уточняется',
  teacher:'Ардашникова Анна Наумовна',
  room_hint:'',
  quality:'01.09.2026: по рабочей версии 29.08 у курса есть дополнительная пара через неделю, но её чётность не была подтверждена. После снятия конфликта с ОВЯ новый слот и чётность намеренно оставлены «уточняется», чтобы не создать ложную еженедельную пару или новую накладку. После подтверждения чётности требуется выбрать аудиторию; лекция должна проходить в обычной аудитории, не на кафедре.'
});

const rows=typeof isServiceRow==='function'?DATA.filter(r=>!isServiceRow(r)):DATA.slice();
PUBLIC_DATA.splice(0,PUBLIC_DATA.length,...rows);
try{if(typeof buildGroupItems==='function')buildGroupItems();}catch(e){}
try{if(typeof buildBrowseList==='function')buildBrowseList();}catch(e){}
try{if(typeof showEmpty==='function')showEmpty();}catch(e){}
})();
